def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5, -5]), fmt([0, 0, 0]), fmt([0, 7]), fmt([1, 2, 3, 4, 5, 6]), fmt([1, 3]),
             fmt([-10**9, 10**9, 5 * 10**8, -5 * 10**8]), fmt([2, -3, 5, 8]), fmt([0, 0, 0, -4, 4])]
    for n in (2, 3, 4, 6, 8, 10, 15, 25):
        for hi in (4, 20, 100):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.choice([-1, 1]) * rng.randint(5 * 10**8, 10**9) for _ in range(N)]))
    tests.append(fmt([rng.choice([-1, 1]) * (2 ** rng.randint(0, 29)) for _ in range(N)]))
    tests.append(fmt([0] * N))
    tests.append(fmt([rng.choice([-1, 1]) * int(1.0001 ** rng.randint(0, 200000)) % (10**9) for _ in range(N)]))
    return tests

